#include <stdio.h>

void abort(void);
void exit(int);

#ifndef STACK_SIZE
#define STACK_SIZE 200000
#endif

__inline__ static int dummy(int x) {
  int y;
  y = (long)(x * 4711.3);
  return y;
}

int getval(void);

int f2(double x) {
  unsigned short s;
  int            a, b, c, d, e, f, g, h, i, j;

  a = getval();
  b = getval();
  c = getval();
  d = getval();
  e = getval();
  f = getval();
  g = getval();
  h = getval();
  i = getval();
  j = getval();

  s = x;

  return a + b + c + d + e + f + g + h + i + j + s;
}

int x = 1;

int getval(void) { return x++; }

char buf[10];

void f() {
  char ar[STACK_SIZE / 2];
  int  a, b, c, d, e, f, g, h, i, j, k;

  a = getval();
  b = getval();
  c = getval();
  d = getval();
  e = getval();
  f = getval();
  g = getval();
  h = getval();
  i = getval();
  j = getval();

  k = f2(17.0);

  sprintf(buf, "%d\n", a + b + c + d + e + f + g + h + i + j + k);
  if (a + b + c + d + e + f + g + h + i + j + k != 227)
    abort();
}

int main(void) {
  f();
  exit(0);
}


